import{z as i,x as B,o as e,c as p,q as r,j as E,D as t,d as l,s as n,S as A}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"Capacity factor","description":"","frontmatter":{"title":"Capacity factor","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/moe-capacity-factor.md","filePath":"llm/moe-capacity-factor.md","lastUpdated":1791413859000}'),m={name:"llm/moe-capacity-factor.md"};function s(h,a,c,C,d,F){const o=B("Mermaid");return e(),p("div",null,[a[2]||(a[2]=r('<h1 id="capacity-factor" tabindex="-1">Capacity factor <a class="header-anchor" href="#capacity-factor" aria-label="Permalink to &quot;Capacity factor&quot;">​</a></h1><div class="epigraph"><p>专家一次能吃下的 token 数不是无限的；容量因子把「想去这个专家的人」裁成一块固定大小的桶，多出来的要么丢掉，要么改道。</p><footer>—— Lepikhin et al., GShard, 2020；Fedus, Zoph, Shazeer, Switch Transformers, 2021</footer></div><p><a href="/llm/moe-inference-cache">上一课</a>把推理侧写成热专家常驻、冷专家按需加载。本课回到训练图里那条更硬的约束：即使专家权重全在 HBM 上，每个专家每个 step 也只能处理有限个 token。GShard 与 Switch 把这条上限写成 <strong>capacity factor</strong>（容量因子）。<a href="/llm/moe-load-balance">负载均衡损失</a>只能软性地把流量往均匀推；容量因子是硬截断。后面的 Dropless、Expert-choice 都默认你会本课的桶大小，不再从「为什么 MoE 要路由」讲起。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/llm/moe-routing">MoE 路由</a>给每个 token 一个 top-\\(k\\) 专家集合。若实现按「谁被点到就算谁」，热专家会在一次 All-to-All 里收到远超本地算力与激活缓冲的 token，冷专家空转。通信缓冲、专家 GEMM 的 batch 维、以及按专家切分的张量形状，都需要在编译期或至少在 step 开始时知道上限。没有上限，图无法静态分配，过载专家还会把整卡打满。</p><p>于是训练必须回答：专家 \\(i\\) 这一步最多处理多少 token？设一批有 \\(T\\) 个 token、一层 \\(N\\) 个专家、每个 token 选 \\(k\\) 个专家，均匀负载下每专家应分到</p> \\[c_{\\mathrm{eq}} = \\frac{kT}{N}. \\]<p>容量因子 \\(\\mathrm{CF}\\) 把实际上限写成 \\(C = \\lceil \\mathrm{CF}\\cdot c_{\\mathrm{eq}}\\rceil\\)。\\(\\mathrm{CF}=1\\) 表示刚好按均匀切；\\(\\mathrm{CF}\\gt 1\\) 留出余量给暂时不均；\\(\\mathrm{CF}\\lt 1\\) 则故意欠载、逼更多 drop。Switch 常用 \\(1.0\\)–\\(1.25\\) 这一档。问题不是「要不要稀疏」，而是：<strong>过载时丢掉哪些 token，以及丢掉之后梯度还算不算 MoE</strong>。</p><p><span class="marginnote">数字实例：一批 \\(T=4096\\) 个 token、\\(N=64\\) 个专家、\\(k=1\\)，均匀负载下每专家分到 \\(4096/64=64\\) 个 token；\\(\\mathrm{CF}=1.25\\) 就是每专家 \\(\\lceil 1.25\\times 64\\rceil=80\\) 个槽。若某个热专家这一步实际来了 200 个 token，多出的 120 个在门口全部被丢。</span></p><h3 id="容量是通信与计算的同一把尺子" tabindex="-1">容量是通信与计算的同一把尺子 <a class="header-anchor" href="#容量是通信与计算的同一把尺子" aria-label="Permalink to &quot;容量是通信与计算的同一把尺子&quot;">​</a></h3><p>All-to-All 的发送缓冲按 \\(N\\times C\\) 开，不是按「这一步实际路由结果」开。\\(\\mathrm{CF}\\) 每加 \\(0.25\\)，缓冲与专家侧 GEMM 的 token 维一起涨。它同时是算力税和显存税。推理缓存课里的 \\(C\\) 是「HBM 里能钉住几个专家权重」；本课的 \\(C\\) 是「一个专家这一步能吞几个激活」。两个 \\(C\\) 不要混用。<span class="marginnote">把容量因子理解成「模型有多宽」是错的。总参数仍是 \\(N\\) 份专家；\\(\\mathrm{CF}\\) 只改每个 step 真正算完的 token–专家对数目，以及有多少对在门口被扔掉。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对每个专家维护一个长度为 \\(C\\) 的槽。路由给出 token \\(t\\) 的专家 \\(e\\) 之后，若 \\(e\\) 的已占用槽 \\(\\lt C\\)，则把 \\(t\\) 写入该槽；否则该 \\((t,e)\\) 对 <strong>drop</strong>：前向里该专家对 \\(t\\) 的贡献视为零（或残差旁路原样穿过），反向里这条边没有专家梯度。Switch 还讨论过把路由概率乘回输出；drop 发生时乘的是零贡献，等价于这个 token 在这一层没走稀疏 FFN。</p><p>实现上常见两种计数。一是按全局 batch 统计 \\(T\\)，所有设备用同一 \\(C\\)。二是按本卡局部 token 数统计，EP 组内再 All-to-All。局部计数在数据并行不均时会让有的卡先满，表现为「同一超参、不同切片 drop 率差一截」。论文数字必须写清 \\(T\\) 是全局还是每卡。</p><h3 id="谁先占用槽-决定谁被丢" tabindex="-1">谁先占用槽，决定谁被丢 <a class="header-anchor" href="#谁先占用槽-决定谁被丢" aria-label="Permalink to &quot;谁先占用槽，决定谁被丢&quot;">​</a></h3><p>槽位分配不是数学恒等，而是一种仲裁。按序列位置从左到右填，会系统性地丢掉右侧 token——长文档的后半段更常被丢。按路由分数从高到低填，保住「路由器最自信」的对，丢掉犹豫的对。按随机排列填，无位置偏见，但不可复现性上升。GShard / Switch 的工程默认多是确定性的位置序或分数序；换序会改有效数据分布，不是无害的实现细节。</p>',16)),(e(),E(A,null,{default:t(()=>[n(o,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20R%5B%22%E8%B7%AF%E7%94%B1%E5%BE%97%E5%88%B0%20token-%E4%B8%93%E5%AE%B6%E5%AF%B9%22%5D%20--%3E%20F%7B%22%E8%AF%A5%E4%B8%93%E5%AE%B6%E6%A7%BD%E4%BD%8D%E6%9C%AA%E6%BB%A1%3F%22%7D%0A%20%20F%20--%3E%7C%22%E6%9C%AA%E6%BB%A1%22%7C%20S%5B%22%E5%86%99%E5%85%A5%E5%AE%B9%E9%87%8F%E6%A7%BD%E5%B9%B6%E5%81%9A%20GEMM%22%5D%0A%20%20F%20--%3E%7C%22%E5%B7%B2%E6%BB%A1%22%7C%20D%5B%22drop%EF%BC%9A%E6%9C%AC%E5%B1%82%E4%B8%93%E5%AE%B6%E8%B4%A1%E7%8C%AE%E4%B8%BA%E9%9B%B6%22%5D%0A%20%20S%20--%3E%20O%5B%22%E5%8A%A0%E6%9D%83%EF%BC%88%E6%88%96%E5%BC%80%E5%85%B3%EF%BC%89%E5%86%99%E5%9B%9E%E6%AE%8B%E5%B7%AE%22%5D%0A%20%20D%20--%3E%20O%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r('<p><span class="marginnote">直觉类比：容量槽像餐厅桌位——按预期客流（均匀负载）乘一个余量系数预留。坐满后新来的客人被拒之门外，这批「没吃上这口饭」的 token 只能靠残差连接「喝水」继续往下走；被拒的下次不一定还来（路由会改道），这就是 drop 会反过来塑造路由分布的原因。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>drop 把稀疏变成<strong>随机深度的近亲</strong>：被丢掉的 token 这一层退回「只走残差 / 共享部分」。若 drop 率长期很高，有效深度变浅，主损失会逼路由器把流量挤进尚未满的专家——这与<a href="/llm/moe-load-balance">辅助损失</a>的均匀先验同向，但辅助损失在 drop 之前就作用，容量因子在 drop 之时作用。只加 \\(\\mathrm{CF}\\)、不加均衡，热专家先满、冷专家仍饿，drop 集中在热专家门口，冷专家依然学不到东西。</p><p>\\(\\mathrm{CF}\\) 与 \\(k\\) 耦合。\\(k=2\\) 时每个 token 占两个槽，同等 \\(T,N\\) 下 \\(c_{\\mathrm{eq}}\\) 翻倍，同样 \\(\\mathrm{CF}\\) 的绝对槽数也翻倍。Switch 把 \\(k\\) 收到 \\(1\\)，一个动机就是让容量账更简单：每个 token 最多占一个专家的一个槽。Mixtral 式 \\(k=2\\)、\\(N=8\\) 时 \\(\\mathrm{CF}=1\\) 意味着每专家 \\(T/4\\) 个槽，看起来很宽裕，但若路由崩到两三个专家，那两三个仍会先满。</p><p><span class="marginnote">评测 drop 不要只报平均值。按专家、按序列位置、按语言 / 代码子批切开会看到：被丢的往往是已经处于分布尾部的 token。平均 drop 率 1% 可以掩盖「某一层某一专家 20%」的局部事故，那种事故会在长训里变成损失尖峰的伏笔。</span></p>',5)),(e(),E(A,null,{default:t(()=>[n(o,{id:"mermaid-60",class:"mermaid",graph:"flowchart%20TD%0A%20%20CF%7B%22%E5%AE%B9%E9%87%8F%E5%9B%A0%E5%AD%90%E9%80%89%E5%A4%9A%E5%A4%A7%EF%BC%9F%22%7D%0A%20%20CF%20--%3E%7C%22%E8%BF%9C%E5%A4%A7%E4%BA%8E%201%22%7C%20BIG%5B%22%E5%87%A0%E4%B9%8E%E4%B8%8D%20drop%EF%BC%9A%E5%9D%87%E8%A1%A1%E6%A2%AF%E5%BA%A6%E5%8F%98%E5%BC%B1%EF%BC%8C%E5%B4%A9%E6%BA%83%E8%A2%AB%E6%8E%A8%E8%BF%9F%22%5D%0A%20%20CF%20--%3E%7C%22%E7%BA%A6%201.0-1.25%22%7C%20MID%5B%22%E7%95%99%E5%B0%91%E9%87%8F%E4%BD%99%E9%87%8F%EF%BC%9A%E5%B8%B8%E8%A7%81%E8%AE%AD%E7%BB%83%E5%B7%A5%E4%BD%9C%E7%82%B9%22%5D%0A%20%20CF%20--%3E%7C%22%E5%B0%8F%E4%BA%8E%201%22%7C%20SMALL%5B%22%E6%95%85%E6%84%8F%E6%AC%A0%E8%BD%BD%EF%BC%9A%E7%B1%BB%E4%BC%BC%20LayerDrop%20%E7%9A%84%E6%AD%A3%E8%A7%84%E5%8C%96%EF%BC%8C%E5%AF%B9%E9%95%BF%E5%B0%BE%E4%B8%8D%E5%85%AC%E5%B9%B3%22%5D%0A%20%20MID%20--%3E%20CHK%7B%22%E7%83%AD%E4%B8%93%E5%AE%B6%E6%98%AF%E5%90%A6%E4%BB%8D%E5%85%88%E6%BB%A1%EF%BC%9F%22%7D%0A%20%20CHK%20--%3E%7C%22%E6%98%AF%22%7C%20BAL%5B%22%E8%AF%A5%E8%B0%83%E7%9A%84%E6%98%AF%E5%9D%87%E8%A1%A1%E6%8D%9F%E5%A4%B1%E6%88%96%E5%81%8F%E7%BD%AE%EF%BC%8C%E4%B8%8D%E6%98%AF%E7%BB%A7%E7%BB%AD%E5%8A%A0%20CF%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=r('<h3 id="容量余量换的是什么" tabindex="-1">容量余量换的是什么 <a class="header-anchor" href="#容量余量换的是什么" aria-label="Permalink to &quot;容量余量换的是什么&quot;">​</a></h3><p>\\(\\mathrm{CF}=1.25\\) 相对 \\(1.0\\)，多付 25% 的专家侧计算与通信，换来更少的硬截断。训练早期路由还在随机游走，余量很值钱；训练后期若辅助损失或偏置已经把 \\(f_i\\) 拉平，余量的边际收益下降，可以逐步把 \\(\\mathrm{CF}\\) 收回来省算力。把它当成全程常数，是图编译图省事，不是最优策略。动态 \\(\\mathrm{CF}\\) 则要能改 All-to-All 形状或始终按峰值开缓冲——后者等于从来没省过。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>容量因子不能替代路由质量。\\(\\mathrm{CF}\\) 很大时几乎不 drop，模型可以靠「所有人挤进好专家、好专家桶够大」活着，均衡损失的梯度变弱，崩溃被推迟到你开始收紧 \\(\\mathrm{CF}\\) 的那天。反过来，\\(\\mathrm{CF}\\lt 1\\) 是一种正规化：强迫一部分 token 跳过 MoE，类似 LayerDrop，但选择集由路由拥塞决定，不是由层号决定，对长尾语言不公平。</p><p>生成服务里没有「按 batch 预留 \\(C\\) 个槽再 All-to-All」这一套时，容量因子通常不再以训练原义出现；decode 逐步、每步 token 少，过载改成<a href="/llm/moe-inference-cache">专家缓存</a>的缺页，而不是 drop。<span class="marginnote">术语翻译：缺页借自操作系统的虚拟内存——CPU 访问的数据不在内存里，硬件触发一次「从磁盘换入」。这里的对应物是专家权重不在 GPU 显存里，要用时触发一次从 CPU 内存或远端加载，代价是毫秒到几十毫秒级的停顿。</span>不要把训练日志里的 drop 率直接翻译成线上 TTFT。微调若冻路由器、只训专家，训练期的 \\(C\\) 仍在，但路由分布已经定型，drop 模式会与预训练不同，需要单独盯。</p><p><span class="marginnote">Switch 文中的容量实验是「同一 FLOPs 预算下 \\(\\mathrm{CF}\\) 怎么选」，不是「\\(\\mathrm{CF}\\) 越大质量越好」。引用时要带上他们当时的 \\(k=1\\)、TPU 切片和辅助损失系数；把 \\(\\mathrm{CF}=2\\) 抄到 GPU EP + top-2 上，桶的绝对大小已经不是同一物件。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>容量因子把每专家每 step 的 token 上限写成 \\(C=\\lceil\\mathrm{CF}\\cdot kT/N\\rceil\\)，是硬截断，不是软损失。</li><li>槽满则 drop：该 token–专家对本层贡献为零；仲裁顺序（位置 / 分数 / 随机）会改有效数据。</li><li>\\(\\mathrm{CF}\\) 同时放大 All-to-All 缓冲与专家 GEMM；余量换的是少 drop，不是更多参数。</li><li>只加大容量、不均衡负载，热专家门口仍丢、冷专家仍饿。</li><li>训练期的 \\(C\\) 与推理期「能缓存几个专家权重」不是同一个量。</li><li>出处：Lepikhin 等，GShard；Fedus、Zoph、Shazeer，Switch Transformers。</li></ul>',8))])}const f=i(m,[["render",s]]);export{D as __pageData,f as default};
